let messagePaneBrowser;
let autodetectCharset;
let selection;
if (!mailContextMenu.selectionIsOverridden) {
  if (window.messageBrowser) {
    if (!window.messageBrowser.hidden) {
      messagePaneBrowser =
        window.messageBrowser.contentWindow.getMessagePaneBrowser();
      autodetectCharset =
        window.messageBrowser.contentWindow.autodetectCharset;
    }
  } else {
    messagePaneBrowser = window.getMessagePaneBrowser();
    autodetectCharset = window.autodetectCharset;
  }
  if (
    messagePaneBrowser &&
    Services.prefs.getBoolPref("mailnews.reply_quoting_selection")
  ) {
    const actor =
      messagePaneBrowser.browsingContext.currentWindowGlobal.getActor(
        "MailMessage"
      );
    selection = await actor.sendQuery("MailMessage:GetSelectionForQuoting");
  }
}

top.ComposeMessage(
  composeType,
  event?.shiftKey
    ? Ci.nsIMsgCompFormat.OppositeOfDefault
    : Ci.nsIMsgCompFormat.Default,
  msgFolder,
  msgUris,
  selection,
  autodetectCharset
);
